mapper.select:
select s.stocktaking_id as stocktakingId, s.stocktaking_no as stocktakingNo, s.warehouse_id as warehouseId, w.warehouse_name as warehouseName, s.stocktaking_date as stocktakingDate, s.stocktaking_mode as mode, s.stocktaking_scope as scope, s.scope_label as scopeLabel, s.stocktaking_status as status, s.expected_quantity as expectedQuantity, s.create_time as createTime, s.remark, case when s.stocktaking_mode = 0 then (select count(1) from ry_business.ry_rental_stocktaking_item i where i.tenant_id = s.tenant_id and i.member_id = s.member_id and i.stocktaking_id = s.stocktaking_id and i.inventory_id is not null and i.is_delete = 0) else s.expected_quantity end as itemCount, case when s.stocktaking_mode = 0 then (select count(1) from ry_business.ry_rental_stocktaking_item i where i.tenant_id = s.tenant_id and i.member_id = s.member_id and i.stocktaking_id = s.stocktaking_id and i.inventory_id is not null and i.counted_quantity is not null and i.is_delete = 0) else (select count(distinct i.scan_code) from ry_business.ry_rental_stocktaking_item i where i.tenant_id = s.tenant_id and i.member_id = s.member_id and i.stocktaking_id = s.stocktaking_id and i.scan_code is not null and i.is_delete = 0) end as completedCount, case when s.stocktaking_mode = 0 then (select count(1) from ry_business.ry_rental_stocktaking_item i where i.tenant_id = s.tenant_id and i.member_id = s.member_id and i.stocktaking_id = s.stocktaking_id and i.difference_quantity <> 0 and i.is_delete = 0) else s.abnormal_count end as abnormalCount from ry_business.ry_rental_stocktaking s inner join ry_business.ry_rental_warehouse w on w.warehouse_id = s.warehouse_id and w.tenant_id = s.tenant_id and w.member_id = s.member_id and w.is_delete = 0 where s.tenant_id = #{tenantId} and s.member_id = #{memberId} and s.is_delete = 0 and s.warehouse_id = #{warehouseId} and s.stocktaking_status = #{status} and s.stocktaking_mode = #{mode} and s.stocktaking_date >= #{beginDate} and s.stocktaking_date <= #{endDate}
and (s.stocktaking_no like concat('%', #{keyword}, '%') or w.warehouse_name like concat('%', #{keyword}, '%'))
and s.warehouse_id in #{id}
and 1 = 0
order by s.create_time desc, s.stocktaking_id desc

select count(case when s.stocktaking_status = 0 then 1 end) as processingCount, count(case when s.stocktaking_status = 3 then 1 end) as pendingReviewCount, count(case when s.stocktaking_status = 1 and date(s.update_time) = current_date then 1 end) as completedTodayCount, coalesce(sum(case when s.stocktaking_mode = 0 and s.stocktaking_status = 3 then (select count(1) from ry_business.ry_rental_stocktaking_item i where i.tenant_id = s.tenant_id and i.member_id = s.member_id and i.stocktaking_id = s.stocktaking_id and i.difference_quantity is not null and i.difference_quantity <> 0 and i.is_delete = 0) when s.stocktaking_mode = 1 and s.stocktaking_status = 0 then s.abnormal_count else 0 end), 0) as abnormalCount from ry_business.ry_rental_stocktaking s where s.tenant_id = #{tenantId} and s.member_id = #{memberId} and s.is_delete = 0 and s.warehouse_id = #{warehouseId}
and s.warehouse_id in #{id}
and 1 = 0

select case when #{scope} = 1
            then coalesce(nullif(concat_ws(' / ', nullif(p.category_level1, ''),
                           nullif(p.category_level2, ''), nullif(p.category_level3, '')), ''), '指定分类')
            else coalesce(nullif(concat_ws(' ', nullif(p.brand, ''), nullif(p.model_name, ''),
                           nullif(p.memory_spec, '')), ''), '指定型号') end
from ry_business.ry_rental_product p
where p.tenant_id = #{tenantId} and p.member_id = #{memberId} and p.status = 0 and p.is_delete = 0

    and p.class_id = #{classId}
    and p.model_id = #{modelId}

order by p.product_id limit 1

choose.otherwise:
select coalesce(sum(i.available_quantity), 0)
from ry_business.ry_rental_merchant_inventory i
inner join ry_business.ry_rental_product p
  on p.product_id = i.product_id and p.tenant_id = i.tenant_id
 and p.member_id = i.member_id and p.is_delete = 0
where i.tenant_id = #{tenantId} and i.member_id = #{memberId}
  and i.warehouse_id = #{warehouseId} and i.status = 0 and i.is_delete = 0
and p.class_id = #{classId}
and p.model_id = #{modelId}

mapper.select:
select count(1) from ry_business.ry_rental_stocktaking_item
where tenant_id = #{tenantId} and member_id = #{memberId}
  and stocktaking_id = #{stocktakingId} and scan_code = #{scanCode} and is_delete = 0

mapper.update:
update ry_business.ry_rental_stocktaking_item
set counted_quantity = #{countedQuantity},
    difference_quantity = #{countedQuantity} - book_quantity
where tenant_id = #{tenantId} and member_id = #{memberId}
  and stocktaking_id = #{stocktakingId} and item_id = #{itemId}
  and inventory_id is not null and is_delete = 0
